pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    address internal deployer;

    function setUp() public {
        deployer = address(this);
        c = new StaxLPStaking(deployer, deployer);
    }

    function testFuzz_property(address otherAddress) public {
        vm.assume(otherAddress != deployer);
        assertTrue(c.owner() == deployer, "owner should be the original deployer");
    }
}
